import{NextRequest,NextResponse}from'next/server';import{z}from'zod';import{requireActiveAdmin}from'@/lib/admin-auth';import{createAdminClient}from'@/lib/supabase/admin'
const schema=z.object({vendorName:z.string().trim().min(1).max(200),category:z.string().trim().min(1).max(100),contactPerson:z.string().trim().max(150).nullable().optional(),mobile:z.string().trim().max(40).nullable().optional(),email:z.string().trim().email().max(320).nullable().optional(),location:z.string().trim().max(150).nullable().optional(),address:z.string().trim().max(1000).nullable().optional(),description:z.string().trim().max(4000).nullable().optional(),internalNotes:z.string().trim().max(4000).nullable().optional()})
export async function GET(r:NextRequest){const a=await requireActiveAdmin();if('response'in a)return a.response;const q=r.nextUrl.searchParams,db=createAdminClient();let query=db.from('event_vendors').select('id,vendor_name,category,contact_person,mobile,email,location,address,description,is_active,internal_notes,created_at,updated_at').order('vendor_name');const search=q.get('search'),category=q.get('category'),contactPerson=q.get('contactPerson'),mobile=q.get('mobile'),active=q.get('active');if(search)query=query.ilike('vendor_name',`%${search}%`);if(category)query=query.eq('category',category);if(contactPerson)query=query.ilike('contact_person',`%${contactPerson}%`);if(mobile)query=query.ilike('mobile',`%${mobile}%`);if(active==='true'||active==='false')query=query.eq('is_active',active==='true');const{data,error}=await query;if(error)return NextResponse.json({error:'Unable to load vendors'},{status:500});return NextResponse.json({vendors:data??[]})}
export async function POST(r:NextRequest){const a=await requireActiveAdmin();if('response'in a)return a.response;let body:unknown;try{body=await r.json()}catch{return NextResponse.json({error:'Invalid JSON'},{status:400})}const p=schema.safeParse(body);if(!p.success)return NextResponse.json({error:'Please check the vendor details',details:p.error.flatten().fieldErrors},{status:400});const{data,error}=await createAdminClient().from('event_vendors').insert({vendor_name:p.data.vendorName,category:p.data.category,contact_person:p.data.contactPerson||null,mobile:p.data.mobile||null,email:p.data.email||null,location:p.data.location||null,address:p.data.address||null,description:p.data.description||null,internal_notes:p.data.internalNotes||null,created_by:a.admin.id}).select('id').single();if(error)return NextResponse.json({error:'Unable to create vendor'},{status:500});return NextResponse.json({vendorId:data.id},{status:201})}
